// The words for memories (Minds.cs): by what it was (a group, or an exact scene kind first), how they knew it (did,
// saw), their part in it (doer, done), how far they've got with it (fresh, chewing, letting go) and, for blows and
// quarrels, their temperament (bold, fearful, cold, plain), so a coward and a hothead who saw the same fight never
// think the same line. "near": someone in it is in sight. Slots: {who} the other one (did), {a} and {b} the two
// seen, {town}. A name is as this person knows it: a first name, or how they looked ("a farmhand"). Short, one detail,
// the outside and the inside apart (Lex's writing brief). All lines are original to this add-on. "{a} and {b}" is rewritten
// to "{a}, {b} and another" only for a told memory (Minds.Drifted's Many), and a told memory is worded by the told pools, so a
// saw line here may say what {a} and {b} both did. A proposal's memory is held by both (the scene's cast order doesn't say
// who asked), so its lines are for either side.
using System.Collections.Generic;
using System.Linq;

namespace EnrageWestworld.Core
{
    public static partial class Minds
    {
        internal static readonly Dictionary<string, string[]> Pools = new Dictionary<string, string[]>
        {
            // ---- blows: a brawl both were in -----------------------------------------------------------
            { "blows|did|fresh|bold", new[] { "Knuckles split on {who}'s jaw. Felt good. God help me, it felt good.", "{who} swung first. I swung last. That's the whole of it.", "Ear's ringing yet. {who} has a right hand on {him}, I'll say that.", "Whole street saw me stand over {who}. Let them talk. Let them." } },
            { "blows|did|chewing|bold", new[] { "Still taste blood from that business with {who}. Copper and dirt.", "Folks step aside for me now. That's what a fight buys.", "{who} hasn't come looking for a second go. Didn't think {he} would.", "Knuckle's gone stiff. Worth every swing I landed on {who}." } },
            { "blows|did|letting|bold", new[] { "Me and {who}, fists in the street. Seems a long way off now.", "Bruise on my knuckles has gone yellow. So has the heat of it.", "Fought {who} once. {he} knows it, I know it. That'll do.", "Scar on my lip from {who}. Wear it like a watch chain." } },
            { "blows|did|fresh|fearful", new[] { "Hands won't stop shaking. {who} could've killed me.", "I hit {who}. Me. Don't know what came over me.", "Fought {who} in the open road. What if {he} comes back with friends.", "My knuckles are raw and I can't recall throwing a punch." } },
            { "blows|did|chewing|fearful", new[] { "Keeping to the back lanes. {who} might still be looking.", "Every loud voice and I flinch. Since {who}.", "Took the alley home again. {who} drinks at the front.", "Dream of {who}'s fists and wake with mine clenched." } },
            { "blows|did|letting|fearful", new[] { "Haven't seen {who} in days. Thank the Lord for small mercies.", "Ribs barely ache now. The fright takes longer.", "Passed {who} in the street today and {he} only grunted. A grunt will do.", "Eye's cleared up. I still can't walk that street at night." } },
            { "blows|did|fresh|cold", new[] { "{who} wanted teaching. Lesson's done. Back to work.", "Wasted a good hour on {who}'s fists. Time is money.", "Two minutes with {who}. A sorry use of a morning.", "{who} bled on my cuff. The laundry costs more than {he}'s worth." } },
            // a memory against a strong belief, read by one who rewrites it in their own favour (Beliefs.Slant, after item 14; MindLive): one's own
            // theft or blows against "an honest man" (deserved), the player's kindness against "dangerous" (a trick), his violence against
            // "kind" (provoked), a death seen against "a decent place" (outsiders)
            { "slant|deserved", new[] { "{who} had it coming. Anybody who was there would say so.", "Started it himself, near enough. I only finished it.", "A man can only be pushed so far. {who} pushed.", "I'd do it again. That's not the same as being sorry." } },
            { "slant|trick", new[] { "{you} was after something, being kind like that. They always are.", "Nobody does a thing for nothing. Not {you}. Watch him.", "Kind today. A man like {you} is kind the way a cat is kind to a mouse.", "A good turn from {you}. I'll be paying for it one way or another." } },
            { "slant|provoked", new[] { "{you} wouldn't have done that for nothing. Somebody pushed him to it.", "There'll have been a reason. There's always a reason with a man like {you}.", "I didn't see the start of it. {you} isn't the sort to start it.", "Whoever he hit had it coming, likely. {you}'s not a cruel man." } },
            { "slant|outsiders", new[] { "Outsiders, that was. Nobody from here does a thing like that.", "Drifters. The town's the same town it was yesterday.", "One bad day doesn't make a bad town. It was strangers.", "It happened here, but it wasn't us. That's the difference." } },
            { "blows|did|chewing|cold", new[] { "Tore a good coat brawling with {who}. Somebody pays for the cloth.", "Men keep talking of the fight with {who}. Let them. Talk is cheap.", "Folk ask about {who}. I say it's finished. It is, until it isn't.", "Fists settle nothing. Accounts do. {who} is on the books." } },
            { "blows|did|letting|cold", new[] { "{who}. Hardly think of it. Hardly.", "Knuckles healed. The grudge kept in a drawer, for later.", "Scrapped with {who} a while back. It changed nothing, which was the point.", "{who} keeps clear. Good. Clear is all I wanted." } },
            { "blows|did|fresh|plain", new[] { "Brawling in the street like a boy. With {who}, of all people.", "Lip's split. Pride too. {who} won't let me forget it.", "Shirt torn at the shoulder. {who} and me, rolling in the road like dogs.", "Hit {who}. Got hit back. Nobody won, whatever they say." } },
            { "blows|did|chewing|plain", new[] { "Ought to make it right with {who}. Ought to. Won't today.", "Mother would've had words about that fight. I can hear her yet.", "Folk ask about the eye. I say a door. They know it was {who}.", "Every time I pass that spot I feel the whole street looking." } },
            { "blows|did|letting|plain", new[] { "{who} and me. Mostly behind us now.", "A fight's a fight. Mostly forgotten, like last week's weather.", "{who} and me shook on nothing. Just stopped glaring, one day.", "The bruises went. Still a bit ashamed of myself over {who}." } },
            { "blows|did|near", new[] { "There's {who}. Look away. Or don't.", "{who}'s across the way. My fists remember before I do.", "{who}, right there. {he} walks like nothing happened.", "There's {who}, nursing that jaw. Good." } },

            // ---- a face put into the bar: the one it was done to, and the one who did it ------------------
            { "rough|did:done|fresh|bold", new[] { "Face into the bar, the whole room watching. {who} won't live long enough to brag.", "Taste of varnish and blood. {who} will answer for that.", "Bar top, face first, in front of the whole room. {who} will learn what that costs.", "Lip's split and the room's still laughing. I'll find {who} sober." } },
            { "rough|did:done|chewing|bold", new[] { "Nose still swollen. Every man in the saloon saw. Every one.", "Keep touching the knife at my belt. Thinking of {who}. Only thinking.", "{who} grins at the bar like a man who's forgot. I haven't.", "Nose has set. The matter with {who} hasn't." } },
            { "rough|did:done|letting|bold", new[] { "Nose set crooked. A reminder of {who} every time I shave.", "Let {who} think it's forgot. Let {him} think it.", "Put my face on the bar, {who} did. {he}'ll not try it twice.", "Months on, and I still want to pay {who} back. Mostly I let it be." } },
            { "rough|did:done|fresh|fearful", new[] { "My face. The bar. {who} didn't even look angry. That's the worst of it.", "Ears still ringing. Don't go back in there. Don't.", "Glass dust in my hair. {who}'s hand on the back of my neck. Can't get it out.", "I didn't fight back. Everyone saw I didn't fight back." } },
            { "rough|did:done|chewing|fearful", new[] { "Took the long way round so I wouldn't pass {who}.", "Can't take a drink without tasting that bar top.", "Haven't been in the saloon since. Tell myself it's the money.", "If {who} so much as looks my way I'll be sick." } },
            { "rough|did:done|letting|fearful", new[] { "I drink at home now. Quieter. Safer. Since {who}.", "Bruise is gone. I still sit facing the door.", "Take the stool nearest the door these days. Since {who}.", "Months since {who} put me down. I still flinch at a chair scraping." } },
            { "rough|did:done|fresh|cold", new[] { "{who} put my face in the bar. Noted. Everything is noted.", "Split lip. Loose tooth. I'll set a price on each.", "{who} chose the bar top. Public. Public has a price.", "Nothing broken. {who} should have broken something. Now I owe {him} less." } },
            { "rough|did:done|chewing|cold", new[] { "{who} owes me a tooth. I keep accounts.", "Others laughed. I remember who laughed.", "Saloon's full of men who saw. I know their names too.", "The barman wiped the bar after. Didn't wipe {who}'s name off my ledger." } },
            { "rough|did:done|letting|cold", new[] { "That business with {who}. It'll keep. Debts keep.", "Not angry. Patient. There's a difference.", "{who}, the bar, the laughing. All of it in the book, none of it rushed.", "Patience costs nothing. {who} will run short of {his} sometime." } },
            { "rough|did:done|fresh|plain", new[] { "Slammed my head on the bar like a sack of meal. {who}, of all men.", "Can't hear right in the left ear since {who} had {his} go.", "Took my hat off the floor and walked out. Didn't look at {who}. Couldn't.", "Nose bled on my good shirt. {who} never said a word, just did it." } },
            { "rough|did:done|chewing|plain", new[] { "Everyone saw. All {town} will know by supper.", "Ought to tell the sheriff about {who}. He'd only laugh.", "Folk nod at me kindly now. The nodding's worse than the bar.", "Keep going over it. What I did to make {who} do that." } },
            { "rough|did:done|letting|plain", new[] { "Swelling's gone down. The shame is slower.", "Haven't been back to that saloon. Don't miss it. Much.", "That night with {who}. I tell it as a joke now. Nearly is one.", "Drink somewhere else these days. Smaller place. Nobody knows." } },
            { "rough|did:done|near", new[] { "{who}'s here. My face goes hot all over again.", "There's {who}. Keep the bar between us.", "{who}, leaning on the same bar. My nose throbs to see {him}.", "There's {who}. Everyone in here is remembering it with me." } },
            { "rough|did:doer|fresh", new[] { "Put {who}'s face in the bar. {he}'ll mind {his} mouth now.", "Heard {who}'s nose go. Didn't care for the sound. Didn't stop.", "Knuckles cut on {who}'s teeth. {he} said the thing twice. Once would have done.", "Room went quiet when I let go of {who}. Quiet's fine." } },
            { "rough|did:doer|chewing", new[] { "Wrist still sore from holding {who} down.", "A few men looked at me different after {who}. Good.", "{who}'s telling it round that I jumped {him}. {he} started it with {his} mouth.", "Barkeep looks at me sideways since {who}. Still pours, though." } },
            { "rough|did:doer|letting", new[] { "{who}. Hardly recall what {he} said to set me off.", "Shouldn't have done {who} like that. Shouldn't have.", "{who} and the bar top. Drink does the thinking some nights.", "Haven't laid hands on a man since {who}. Trying to keep it that way." } },
            { "rough|did:doer|near", new[] { "{who} won't meet my eye. That's as it should be.", "There's {who}, nose and all.", "There's {who}. {he} touches {his} nose when {he} sees me. Good.", "{who} across the room, picking a table far from mine. Wise." } },

            // ---- a fight seen ------------------------------------------------------------------------------
            { "blows|saw|fresh|bold", new[] { "{a} and {b}, going at it. Neither would last a minute with me.", "Watched {a} and {b} scrap. Itched to join in.", "{a} and {b}, swinging like they'd never been taught. Somebody ought to teach them.", "Stood close enough to feel {a}'s fist go past. Didn't step back." } },
            { "blows|saw|chewing|bold", new[] { "{a} fights like a mule kicks. All noise.", "Still thinking how I'd have put {b} down quicker.", "{a} and {b} would both go down to a man who knew his trade. Mine, say.", "Keep seeing {b}'s guard drop. I'd have been in under it." } },
            { "blows|saw|letting|bold", new[] { "That set-to between {a} and {b}. Poor show, all told.", "Town's quiet again since {a} and {b}. Too quiet.", "That fight. {a} won it, {b} says otherwise. Neither could stand up to me.", "Nobody's thrown a punch in {town} since {a} and {b}. Pity." } },
            { "blows|saw|fresh|fearful", new[] { "{a} and {b}, fists up in the road. Kept my head down. Kept walking.", "Blood on the boards. Heart going like a rabbit's.", "{a} and {b}, and me behind the water trough. Nobody saw me hide. I hope.", "Got out of there before it spread. Fights spread." } },
            { "blows|saw|chewing|fearful", new[] { "Saw what {a} did to {b}. Don't cross {a}. Not ever.", "Keep seeing that fight when I shut my eyes.", "Go the long way round {a}'s place now. Both ways.", "Hands still shake telling it. {a} and {b}, and all that blood." } },
            { "blows|saw|letting|fearful", new[] { "Town's calm again. For now. Since {a} and {b}.", "Thought of that fight less today. Getting better.", "Fight in the street, a while back. I still look up when a voice rises.", "{a} and {b} nod to each other now. I still can't look {a} in the eye." } },
            { "blows|saw|fresh|cold", new[] { "{a} and {b} brawling. Bad for business, brawling.", "Somebody will pay for that broken chair. Not me.", "{a} and {b} fighting over nothing a man could spend.", "Watched the fight from the step. Cheaper than the theatre." } },
            { "blows|saw|chewing|cold", new[] { "{a} lost a day's wage to that fight. Fool.", "Watched {b} after. Limping. A day's wage lost, and the whole street saw it.", "{b} bled a dollar's worth of shirt. For what.", "{a} and {b} will both want a drink to forget it. Somebody will profit." } },
            { "blows|saw|letting|cold", new[] { "{a} and {b}. Old news. Nobody profits by old news.", "Fights come and go. Accounts stay.", "{a} and {b}. I could tell you who won, and it wouldn't be worth the breath.", "A fight's a line in the ledger. That one's long paid." } },
            { "blows|saw|fresh|plain", new[] { "{a} and {b} going at it like dogs. Grown men.", "Never seen {a} so red in the face. Or {b} so pale.", "{a} and {b}, fists and spit and the whole street. Children watching, too.", "Somebody should've stepped in. I'd like to say I did." } },
            { "blows|saw|chewing|plain", new[] { "Wonder what set {a} and {b} off. Somebody always knows.", "Wiped a fleck of blood off my boot. Not mine.", "Hat still in the road, one of theirs. {a}'s, I think.", "Told the tale at supper. {a} and {b}. It grows every time." } },
            { "blows|saw|letting|plain", new[] { "That business with {a} and {b}. Half the town's forgot.", "Fists in the street. Seems a long while back.", "{a} and {b} drink in the same saloon now. Funny how it goes.", "A fight on that corner, once. Still think of it passing." } },
            { "rough|saw|fresh|bold", new[] { "{a} put {b}'s face in the bar. I'd have done it cleaner.", "Saw {b} go down on the bar top. Didn't look away. Didn't want to.", "{a} had {b} by the collar before {b} finished the word. Quick hands.", "Whole saloon stood back. I stood forward. Nobody noticed." } },
            { "rough|saw|fresh|fearful", new[] { "{a} took {b} by the neck and slammed {b} down. Just like that.", "The sound {b}'s head made on the bar. Can't stop hearing it.", "Bar top, glass, {b}'s head. I left my drink and went.", "{a} didn't shout. That's what frightens me. {he} just did it." } },
            { "rough|saw|fresh|cold", new[] { "{a} broke {b} on the bar. Barman will want paying for the glass.", "{b} had it coming, likely. Most do.", "{a} slammed {b} down and went back to {his} drink. Tidy.", "A nose for a word. {b} paid dear for cheap talk." } },
            { "rough|saw|fresh|plain", new[] { "{a} slammed {b}'s face down on the bar. Glasses jumped.", "Saw {b} go down. Nobody lifted a hand. Nor did I.", "Saw {b}'s face hit the bar. Something went in me. Still hasn't come back.", "{a} did that to {b} like it was nothing. It wasn't nothing." } },

            // ---- words between them ----------------------------------------------------------------------
            { "quarrel|did|fresh|bold", new[] { "{who} spoke to me like I was dirt. Won't happen twice.", "Should've hit {who}. Words weren't enough.", "{who} wants to shout? Shout. I'll be the last one standing when it's done.", "Said it to {who}'s face, loud enough for the street. Let them hear." } },
            { "quarrel|did|chewing|bold", new[] { "Keep thinking of things I should've said to {who}. Good ones, too.", "{who} better not look at me sideways today.", "Half of {town} heard me and {who}. Good. Let them know where I stand.", "{who} started it with {his} mouth. {he} can finish it with {his} fists, if {he} likes." } },
            { "quarrel|did|letting|bold", new[] { "{who} and that mouth. Not worth the trouble.", "Hard words with {who}. Seems smaller now.", "That row with {who}. Blew over. Most things do when you don't back down.", "{who} keeps {his} voice down round me now. That's all I wanted." } },
            { "quarrel|did|fresh|fearful", new[] { "Raised my voice to {who}. Why did I do that.", "{who} looked fit to kill. Over a few words.", "Said too much to {who}. Lay awake going over which part.", "Heart's still going. Hours since {who} and I shouted." } },
            { "quarrel|did|chewing|fearful", new[] { "Crossed the street when I saw {who}. I know what that makes me.", "Keep going over what I said to {who}. Every word worse.", "What if {who} tells people what I said? What did I say?", "Went out the back way twice this week, so as not to meet {who}." } },
            { "quarrel|did|letting|fearful", new[] { "{who} nodded to me today. Nodded. Maybe it's over.", "Words with {who}, and nothing came of it. Nothing yet.", "{who} and I passed and nothing happened. Breathed out for the first time in days.", "That quarrel. I still rehearse what I'd say if {who} brought it up." } },
            { "quarrel|did|fresh|cold", new[] { "{who} shouted. I didn't. I won.", "Let {who} shout. Shouting's free. Grudges aren't.", "{who} raised {his} voice. Men who shout have already lost.", "Said three words to {who}. Chose them. {he} said fifty and chose none." } },
            { "quarrel|did|chewing|cold", new[] { "{who} thinks the matter's closed. It isn't.", "Remember every word {who} said. Every one.", "Wrote down what {who} said. I keep a page for such things.", "{who} will want it forgotten. I'll decide what's forgotten." } },
            { "quarrel|did|letting|cold", new[] { "{who}. Small mind, loud voice.", "That quarrel. Filed away with the rest.", "That quarrel with {who}. A small debit. Still on the page.", "{who} thinks we're past it. We're as past it as I say." } },
            { "quarrel|did|fresh|plain", new[] { "Words with {who}. Stomach's in a knot.", "Shouldn't have said that to {who}. True, though.", "Hard words with {who}. Neither of us meant half. The half we meant was bad enough.", "Ears hot still. {who} and me, shouting in the street like fishwives." } },
            { "quarrel|did|chewing|plain", new[] { "Ought to make peace with {who}. Not yet. Not yet.", "Kept hearing {who}'s voice while I worked.", "Keep seeing {who}'s face as {he} turned away. Ought to go round.", "Can't eat right. Words with {who} sitting in my stomach." } },
            { "quarrel|did|letting|plain", new[] { "Had words with {who}. Can't rightly recall what about.", "{who} and me. Same as ever, near enough.", "{who} and I nod now. Not friends. Nodding's enough.", "A quarrel with {who}, a while back. We let it lie, both of us." } },
            { "quarrel|did|near", new[] { "{who}. Don't catch that eye.", "There's {who}, pretending not to see me.", "There's {who}. Which of us looks away first.", "{who}, ten paces off. The street's got narrow all at once." } },
            { "quarrel|saw|fresh", new[] { "{a} and {b} going at each other. Half the street listening.", "Heard {a} shout at {b}. Everyone heard.", "{a} and {b} at it on the corner, loud enough to wake the dead.", "Never heard {b} shout before. {a} brought it out." } },
            { "quarrel|saw|chewing", new[] { "{a} and {b}. That's been coming a while.", "Somebody ought to talk sense into {a}.", "{a} and {b} are still not speaking. The whole street walks between them.", "{a} crossed the street to miss {b} today. So that's not over." } },
            { "quarrel|saw|letting", new[] { "{a} and {b} have quieted down. For now.", "That old quarrel, {a} and {b}. Town's tired of it.", "{a} and {b} on speaking terms again, more or less.", "That row between {a} and {b}. Nobody recalls what it was about, least of all them." } },

            // ---- a slight: turned away, sent off, avoided -------------------------------------------------
            { "slight|did|fresh", new[] { "Cold words between me and {who}.", "{who} wouldn't hear me out.", "Nodded to {who}. {he} looked at the ground. The ground.", "Took my hand back. {who} wasn't going to shake it." } },
            { "slight|did|chewing", new[] { "What has {who} got against me? Can't think.", "Cheeks still burn when I think of {who}.", "Go over every word I ever said to {who}. Which one did it.", "{who} was civil to the butcher. Civil. Not to me." } },
            { "slight|did|letting", new[] { "{who} can keep that nose in the air.", "Small thing, {who}'s slight. Small things stick.", "{who}'s cold shoulder. I've worn warmer coats and colder ones.", "Whatever I did to {who}, it's gone stale. Let it." } },
            { "slight|did:done|fresh", new[] { "{who} looked right through me. Like I wasn't there.", "Turned away. {who} turned me away.", "{who} crossed the street rather than pass me. Saw it plain.", "Asked {who} a civil question and got the back of {his} head." } },
            { "slight|did:doer|fresh", new[] { "Sent {who} off with nothing. Felt bad after. A little.", "Couldn't face {who} today. Walked the other way.", "Turned my back on {who}. Didn't have the words. Didn't want them.", "{who} wanted a word. I didn't have one to spare." } },
            { "slight|did:doer|chewing", new[] { "Was I too hard on {who}? Maybe.", "{who} looked hurt. Nothing I can do about that.", "Should've stopped for {who}. There was time. There was.", "{who} keeps {his} eyes down now. That's my doing." } },
            { "slight|did:doer|letting", new[] { "{who}. Hardly think of it now.", "Some days you've nothing to give. That was one.", "Was short with {who} once. {he}'s forgotten. I've nearly.", "{who}. Could've been kinder. Wasn't. Next time." } },
            { "slight|did|near", new[] { "{who}'s here. Wonderful.", "There's {who}. Chin up. Walk on.", "{who}, not looking my way. Fine. Two can not look.", "There's {who}. I'll give {him} the same nothing {he} gave me." } },
            { "slight|saw|fresh", new[] { "{b} gave {a} the cold shoulder. Plain as day.", "Saw {a} turned away. Poor thing.", "{b} walked past {a} without a word. {a} just stood there.", "Watched {a} get nothing from {b}. Not a nod. Hard thing to watch." } },

            // ---- a hand in a coat ------------------------------------------------------------------------
            { "pickpocket|did:doer|fresh", new[] { "Caught with my hand in {who}'s coat. Like a schoolboy.", "Ran from {who}. Lungs still burning.", "{who} shouted thief. Thief. Whole street turned.", "Hand went in {who}'s pocket and {his} came down on my wrist. Still feel it." } },
            { "pickpocket|did:doer|chewing", new[] { "Every lawman looks at me twice now. Every one.", "{who} will have told the whole town by now.", "Keep my hands in my own pockets now. Everyone's looking.", "Barkeep won't serve me. {who}'s telling, that is." } },
            { "pickpocket|did:doer|letting", new[] { "{who} has stopped telling it. Or I've stopped listening.", "Lord forgive me, it was only a purse. I never got it.", "Caught at {who}'s pocket, once. Nobody says it. Everybody knows it.", "Went straight for a while after {who}. Mostly straight." } },
            { "pickpocket|did:done|fresh", new[] { "{who} had a hand in my coat. In broad daylight.", "Caught {who} at my pocket. Heart's still racing.", "Felt the tug at my coat. Turned, and there was {who}'s hand.", "{who}'s fingers in my pocket, in the middle of {town}. Nerve." } },
            { "pickpocket|did:done|chewing", new[] { "Keep patting my coat. Still there. Still there.", "Should've held {who} for the law. Should've.", "Count my coins morning and night now. {who}'s doing.", "Everybody's asking what {who} got. Nothing. It's the nothing that galls." } },
            { "pickpocket|did:done|letting", new[] { "Sewed a new pocket inside the coat. Thanks to {who}.", "{who} and the light fingers. Tell everybody I meet.", "{who} tried my pocket, once. I still button my coat to the chin.", "Nearly robbed by {who}. Tell it for a laugh now. Wasn't one then." } },
            { "pickpocket|did|near", new[] { "That's {who}. Hand on my purse.", "There's {who}. Watching me back, I'll bet.", "{who}. Hand goes to my pocket without my asking.", "There's {who}. Walk wide and keep the purse side away." } },
            { "lift|did:doer|fresh", new[] { "{who}'s purse, light as a feather. Easy. Too easy.", "Hand in {who}'s coat and out again. Heart in my mouth.", "{who} never turned round. Never felt a thing.", "Weight of {who}'s purse in my coat. Heavier than it looks." } },
            { "lift|did:doer|chewing", new[] { "Spent {who}'s money already. Gone like smoke.", "{who} hasn't missed it yet. Or has, and said nothing.", "Drank {who}'s money. Tasted the same as mine.", "{who} was asking after a lost purse. Lost. I said I hoped {he} found it." } },
            { "lift|did:doer|letting", new[] { "{who} never knew. Or never said.", "Lord forgive me, it was only a purse.", "{who}'s purse. One of many. Can't recall the colour.", "Lifted off {who} once. {he} nods to me still. That's the trade." } },
            { "lift|did:done|fresh", new[] { "Purse gone. Somewhere between the store and here.", "Coins gone from my coat. Didn't feel a thing.", "Reached for my purse and there was nothing but lining.", "Money gone. Some hand did that, and I never felt it." } },
            { "lift|did:done|chewing", new[] { "Somebody in {town} has my money and a clean face.", "Keep looking at folk's hands now. Every one of them.", "Can't look at a stranger's hands without counting my coins.", "Whoever took it is drinking it. Somewhere in {town}." } },
            { "lift|did:done|letting", new[] { "Lost a purse in {town}. Lesson learned, dear as it was.", "Money's gone. Stopped looking for it in every face.", "Lost a purse once. Never did find out who. Never will.", "That purse. Gone like the money in it. I carry less now." } },
            { "pickpocket|saw|fresh", new[] { "{a} caught with a hand in {b}'s coat. Bold as brass.", "Saw {b} grab {a}'s wrist. Right at the pocket.", "{a} had {his} hand in {b}'s coat before I could blink.", "{b} caught {a} at it. Street went quiet, then loud." } },
            { "pickpocket|saw|chewing", new[] { "Watching {a}'s hands from now on.", "Patted my coat twice since. {a}'s doing.", "Button my coat when {a} is near. Everybody does.", "Still wonder what {a} needed that bad. Or if it was need." } },
            { "pickpocket|saw|letting", new[] { "{a}, the light-fingered one. Town won't forget.", "That business with {a}'s fingers. Old news.", "{a}'s fingers. Old story. Folk still check their pockets after {he} passes.", "{a} at {b}'s pocket, that time. {town} has a long memory for a thief." } },

            // ---- a drunk calling a man out -------------------------------------------------------------
            { "drunk|did:doer|fresh", new[] { "Head's splitting. Did I call {who} out? I think I did.", "Woke on the boards. Whiskey and sawdust.", "Head full of hammers. Did I say that to {who}? Somebody says I did.", "Called {who} out, they tell me. Can't recall what {he}'d done. Likely nothing." } },
            { "drunk|did:doer|chewing", new[] { "{who} has me down for a fool. Can't say {he}'s wrong.", "Swearing off drink. Again.", "Can't walk in the saloon without somebody doing my fall for me.", "{who} was civil about it. That's worse, somehow." } },
            { "drunk|did:doer|letting", new[] { "That night with {who}. Best forgot.", "Few days dry. Hands shake less.", "The night I called {who} out. {he} laughs about it. I'm learning to.", "Stayed off it a week. Hands steady. Mostly." } },
            { "drunk|did:doer|near", new[] { "{who}'s here. Look at the floor. Same floor I lay on.", "There's {who}. Does {he} remember? Course {he} does.", "{who}. The man I called out, flat on my face. There {he} is, upright.", "There's {who}. Hat down. Maybe {he} won't know me sober." } },
            { "drunk|did:done|fresh", new[] { "{who}, drunk as a lord, calling me out. Then flat on {his} face.", "Had to laugh at {who}. Had to.", "{who} squared up to me and the floor got {him} first.", "Swaying, {who} was. Called me every name. Then down like a sack." } },
            { "drunk|did:done|chewing", new[] { "Wonder if {who} remembers any of it. Doubt it.", "Smell of {who}'s breath. Still in my nose.", "{who} tipped {his} hat to me today. No idea what {he}'d said to me. I do.", "Everybody's still laughing about {who}. I've stopped. Sorry sight." } },
            { "drunk|did:done|letting", new[] { "{who}'s sober now, they say. For now.", "Poor {who}. Whiskey's a hard master.", "{who} and the whiskey, that night. Not the worst thing I've seen drink do.", "Don't hold it against {who}. The bottle said it, not {him}." } },
            { "drunk|saw|fresh", new[] { "{a} called {b} out, then fell flat. Whole saloon laughed.", "Drunk as a fiddler, {a}. Sad to watch.", "{a} called {b} out, took one step and the floor had {him}.", "Saw {a} go down. {b} never raised a hand. Didn't need to." } },
            { "drunk|saw|chewing", new[] { "{a} will pay for that whiskey twice. Once at the bar.", "Somebody ought to keep {a} from the bottle.", "{a} hasn't shown {his} face in the saloon since. Can't blame {him}.", "Whole town's telling it. {a} and the floor. Poor devil." } },
            { "drunk|saw|letting", new[] { "{a}'s been quieter since that night.", "Whiskey makes fools of better men than {a}.", "{a} drinks slower now, I notice. Since that night.", "That business with {a} and the whiskey. Told it so often it's lost its sting." } },

            // ---- warmth: a kind word, a smile, a quarrel mended ------------------------------------------
            { "warmth|did|fresh", new[] { "{who} smiled at me. Can't stop thinking of it.", "Warm in the chest. {who}'s doing.", "{who} said my name like it was worth saying.", "Walked home the long way. Didn't want {who}'s words to wear off." } },
            { "warmth|did|chewing", new[] { "Wonder if {who} thinks of me. Hope so.", "Straightened my collar twice. In case {who} comes by.", "Caught myself humming. {who}'s doing, that.", "Find reasons to pass {who}'s door. Poor reasons." } },
            { "warmth|did|letting", new[] { "{who}. A pleasant thing to think on.", "Kind words with {who}. Small, but it carried me.", "{who}, and that afternoon. I keep it where I keep the good things.", "Whatever comes of {who} and me, I had that day." } },
            { "warmth|did|near", new[] { "There's {who}. Stand up straight.", "{who}'s near. Act natural. Natural.", "{who}'s here. Say something. Anything. Not that.", "There's {who}. Hands go cold, face goes hot. Fine way to be." } },
            { "propose|did|fresh", new[] { "{who} and me, and the question asked at last. Lord, my knees.", "It's said, between {who} and me. Can't be unsaid now.", "The question's out in the open, {who} and I. The whole street heard it.", "Asked and answered, {who} and me. Still shaking a little." } },
            { "propose|did|chewing", new[] { "Keep turning over {who}'s face at the asking.", "{who} and me, and a ring to find the money for.", "The answer, over and over, in {who}'s voice and mine.", "Told nobody about {who} and the asking. They'll see it in my face anyhow." } },
            { "makeup|did|fresh", new[] { "Made it right with {who}. Weight off my chest.", "Shook hands with {who}. Like a stone rolled off.", "{who} and I, square again. Didn't know how heavy it sat till it lifted.", "Said sorry to {who}. {he} said it back. Simple as that, after all those months." } },
            { "makeup|did|chewing", new[] { "Easier to walk past {who}'s door now.", "Odd, not being sore at {who}. Feels like a missing tooth.", "Nodded to {who} this morning and meant it. First time in a long while.", "Keep expecting to be sore at {who}. Reach for it and it's not there." } },
            { "charity|did:doer|fresh", new[] { "Gave {who} what I could. Not much. Something.", "Coin to {who}. Felt it leave the pocket. Felt better for it.", "Two bits to {who}. Could have been me asking, another year.", "{who} looked at the coin like it was a meal. It was, likely." } },
            { "charity|did:doer|chewing", new[] { "Hope {who} ate today.", "{who} had the look of someone who hadn't eaten. I knew that look once.", "Saw {who} with bread this morning. Mine, in a way.", "Think of {who} when I eat. Makes the bread go down slower." } },
            { "charity|did:doer|letting", new[] { "Giving to {who} did me more good than {who}, maybe.", "{who}. Wonder how it's going for {him}.", "Gave {who} a coin once. Would like to think it mattered.", "{who}'s moved on, or done better, or worse. I gave what I gave." } },
            { "charity|did:done|fresh", new[] { "{who} gave me a coin. Didn't have to.", "Somebody in {town} still has a heart. {who}.", "{who} put a coin in my hand and didn't make me ask twice.", "Ate tonight. {who}'s coin. God keep {him}." } },
            { "charity|did:done|chewing", new[] { "Bread from {who}'s coin. Best I've had in a week.", "Ought to pay {who} back. Will. Someday.", "Still have one of {who}'s coins. Don't want to spend the last one.", "{who} nodded to me today, like I was anybody. That's the gift, more than the coin." } },
            { "charity|did:done|letting", new[] { "{who}. Won't forget it. Won't.", "One kind face in {town}. {who}'s.", "When I'm on my feet, {who} gets it back double.", "{who}, and a coin, and a bad week. Kept me going. Still does." } },
            { "scorn|did:done|fresh", new[] { "Asked {who} for a coin. Got a look like I was dirt.", "{who} told me to find work. As if I hadn't looked.", "{who} looked at my hand and then at the sky. Not even a no.", "Asked {who}. {he} said {he}'d nothing. {his} boots said otherwise." } },
            { "scorn|did:doer|fresh", new[] { "{who} wanted a coin. Should get work like the rest of us.", "Sent {who} off. If I give to one, I give to all.", "{who} with {his} hand out again. My coin's for my own.", "Told {who} no. The look {he} gave me. Still, no." } },
            { "warmth|saw|fresh", new[] { "{a} and {b}, sweet as pie. Nice to see, for once.", "Saw {a} make {b} laugh. Haven't laughed like that in years.", "{a} and {b}, walking slow so it would last. Sweet, that.", "Saw {a} fix {b}'s collar. Small thing. Says everything." } },
            { "warmth|saw|chewing", new[] { "{a} and {b}. Wedding by summer, mark me.", "Wonder what {a} sees in {b}. Or the other way.", "{a} and {b}. Half the town's picking a wedding hat already.", "Can't pass {a}'s door without wondering if {b}'s inside." } },
            { "warmth|saw|letting", new[] { "{a} and {b}. Old news, sweet news.", "Folk still talk of {a} and {b}. Let them.", "{a} and {b}. Still together, I hear. Good for them.", "That spring {a} and {b} courted. Nice thing to have seen." } },

            // ---- talk ----------------------------------------------------------------------------------
            { "talk|did|fresh", new[] { "Passed the time with {who}. Nothing said, much. Nice, though.", "{who} talks like a creek runs. Never stops.", "{who} had a tale about a mule. Don't know if I believe it. Enjoyed it.", "Half an hour with {who} and the day went easier." } },
            { "talk|did|chewing", new[] { "{who} said something that stuck. Can't think what.", "Must remember what {who} told me.", "{who} asked after my people. Can't think when anyone last did.", "Something {who} said about the weather. Turned out right." } },
            { "talk|did|letting", new[] { "Talked with {who} a while back. Pleasant enough.", "{who}. Good for a word in passing.", "{who}. We talked once, a while back. Didn't mind it.", "Had words with {who}, the pleasant kind. Few enough of those." } },
            { "talk|did|near", new[] { "{who} again. Bound to talk my ear off.", "There's {who}. Nod and keep moving.", "{who}, coming this way. Got a minute. Got two, even.", "There's {who}. Hope {he}'s short on news today." } },
            { "talk|saw|fresh", new[] { "{a} and {b}, jawing again.", "Wonder what {a} and {b} find to talk about.", "{a} and {b} on the corner, going at the weather like it owed them money.", "Saw {a} and {b} talking. {a} doing most of it." } },
            { "gossip|did|fresh", new[] { "{who} had news. Not all of it true, I'd wager.", "Swapped stories with {who}. Gave a little, got more.", "{who} told me a thing about the storekeeper. Don't repeat it. Well.", "Heard three things from {who}. Two can't both be true." } },

            // ---- the player's deeds, seen with their own eyes ({you}: him as they know him) ---------------------
            { "deed:violence|saw|fresh|bold", new[] { "Saw {you} put a man down. Didn't blink. Neither did I.", "{you} did it in plain sight. Bold. I'll give him that.", "{you} dropped him before he'd cleared leather. Never saw a man so quick.", "Stood my ground while {you} did it. Most ran. I counted who ran." } },
            { "deed:violence|saw|chewing|bold", new[] { "Keep thinking how {you} stood after. Easy. Like hanging up a coat.", "Town looks at {you} the way it ought to look at me.", "Could I do what {you} did and walk off whistling? I'd like to think so.", "{you} killed a man and the town stepped aside for him. Men step aside for me too. Not like that." } },
            { "deed:violence|saw|letting|bold", new[] { "{you} and that business. Folks have stopped whispering. I haven't.", "Seen men die before. {you} made it look like work.", "The one {you} shot. Can't recall his face. Recall {you}'s.", "A man died in front of me, {you}'s doing. I've seen worse. Not closer." } },
            { "deed:violence|saw|fresh|fearful", new[] { "{you} killed a man. Right there. I was close enough to hear it.", "My legs went to water. {you} looked right past me. Thank God. Past me.", "I was nearest. If {you} had turned a foot to the left.", "Gunsmoke in my nose still. {you} didn't even hurry." } },
            { "deed:violence|saw|chewing|fearful", new[] { "Can't stop seeing it. {you}, and the man going down.", "Bolted the door twice. Doesn't help. {you} is still out there.", "Jump at every door. {you} could be behind any of them.", "Haven't told the law what I saw of {you}. Won't. {you} might hear." } },
            { "deed:violence|saw|letting|fearful", new[] { "Some nights I still hear it. What {you} did.", "Days now. I still check the window for {you}.", "That killing. It's gone grey, but it's not gone.", "Months on. Still walk the far side from where {you} did it." } },
            { "deed:violence|saw|fresh|cold", new[] { "{you} killed a man. Not my business. Not my loss.", "Saw it. Said nothing. Saying nothing keeps a body breathing.", "{you} shot a man. The man's debts die with him, I suppose. Somebody's loss.", "One less mouth in {town}. {you} did the arithmetic." } },
            { "deed:violence|saw|chewing|cold", new[] { "Somebody will want to know what I saw of {you}. It'll cost them.", "Dead man's boots were better than mine. Shame about him.", "Men pay to hear what I saw {you} do. I've been paid twice.", "The widow will sell up. There's always a buyer after a killing." } },
            { "deed:violence|saw|letting|cold", new[] { "That killing. {you}. A fact, like the price of flour.", "Folks forget. I don't. I just don't care.", "{you}'s killing. Old as last year's prices, and about as interesting.", "Saw a man shot. Kept my own counsel. Kept my own skin." } },
            { "deed:violence|saw|fresh|plain", new[] { "{you} killed a man in front of me. In front of me.", "Saw the whole of it. {you}, then the body. My hands won't keep still.", "{you} shot him and then the quiet. I'll never forget that quiet.", "Blood in the dust. Somebody's son. {you} walked off." } },
            { "deed:violence|saw|chewing|plain", new[] { "Keep thinking of his folks. The one {you} killed.", "Told it twice already. It doesn't get smaller in the telling.", "Pray for the man {you} killed. Pray a little for {you}, too. Don't know why.", "Dreamt of it again. {you}, the shot, the quiet after." } },
            { "deed:violence|saw|letting|plain", new[] { "Days since. I still cross the street from {you}.", "What {you} did. Gets quieter. Doesn't go.", "The man {you} killed had a name. I've forgotten it. Shame on me.", "That shooting. Town's forgot it. I'm a step behind." } },
            { "deed:violence|saw|near", new[] { "There's {you}. The one I saw do it. Look away.", "{you}, close enough to spit at. I won't. I'm no fool.", "{you}. Hands where I can see them, please God.", "There's {you}. Everybody on this street is pretending they didn't see it." } },
            { "lawkill|saw|fresh", new[] { "{you} shot a lawman. A lawman. The whole town will pay for it.", "Badge in the dirt, and {you} walking off. Lord help us.", "{you} shot the law. Whoever comes to replace him will come hard.", "A lawman dead in the road and {you} not even running. Lord." } },
            { "deed:theft|saw|fresh", new[] { "Saw {you} help himself. Nobody stopped him. Nobody ever does.", "{you}, pockets full of what wasn't his. Bold as you please.", "{you} took it like it was owed him. Right off the counter.", "Watched {you} rob the place. Looked at me once. I looked at my boots." } },
            { "deed:theft|saw|chewing", new[] { "Lock the till twice now. Since {you}.", "Wonder whose turn it is next. With {you} about.", "Keep the strongbox under the bed now. {you}'s doing.", "Tell the children to stay in when {you} rides through." } },
            { "deed:theft|saw|letting", new[] { "That thieving. {you}. Town's added it to the tally.", "A thief's a thief. Even one with a fine horse.", "{you}, the thief. I say it plain now. Took a while.", "What {you} stole is long spent. The taking's what folk recall." } },
            { "deed:theft|saw|near", new[] { "There's {you}. Keep my coat buttoned.", "{you} again. Count the spoons after.", "{you}'s here. Hand on the purse, eye on the door.", "There's {you}. Everything I own is in this coat and he knows it." } },
            { "looting|saw|fresh", new[] { "Saw {you} go through a dead man's pockets. Cold as a well.", "{you} robbed the dead. Even outlaws used to let a corpse keep its boots.", "{you} turned a dead man out like a sack. Took his watch.", "Saw {you} at a corpse's pockets. Didn't even close the eyes first." } },
            // a fall: helped up, or walked past ({who} is the other one); the player's own hand up (helpup, {you})
            { "help|did:doer|fresh", new[] { "Helped {who} up out of the dirt. Felt good, that.", "{who} went down hard. Glad I was near.", "Dust on my knees from kneeling by {who}. Don't mind it.", "Got {who} up and dusted off. Knees creak, but that's nothing." } },
            { "help|did:doer|chewing", new[] { "Hope {who}'s ankle mends.", "{who} thanked me twice. Once was plenty.", "{who} limping this morning. Hope it's nothing.", "Passed {who} today. Walking easier. Good." } },
            { "help|did:doer|letting", new[] { "{who}. A small thing I did. Nice to think of.", "Helped {who} up, once. Small thing. Still glad of it.", "Picked {who} up off the road, once. {he} still nods for it.", "A hand up for {who}, a while back. Small, and it stayed with me." } },
            { "help|did:done|fresh", new[] { "{who} picked me up off the street. Didn't have to.", "Face still hot. But {who} was kind about it.", "Ground came up fast. {who}'s hand came quicker.", "{who}'s hand under my arm before I'd finished falling. Kind." } },
            { "help|did:done|chewing", new[] { "Owe {who} a kindness now.", "Knee's purple yet. {who} stopped, though. That's what I'll keep.", "Everyone saw me fall. {who} made it a small thing.", "Told the folk at home who it was helped me up. {who}. They nodded." } },
            { "help|did:done|letting", new[] { "{who} helped me up, the day I fell. Good sort.", "Took a tumble, once. {who} was there. That's what I remember.", "{who} got me on my feet, that day. I think of it when I see {him}.", "Went down in the street, once. {who} was the one who stopped." } },
            { "help|saw|fresh", new[] { "{a} went straight to {b} when {b} fell. Decent.", "Saw {a} help {b} up. Some good left in this town.", "{b} hit the dirt hard. {a} was at {b}'s side before the dust settled.", "Saw {a} kneel in the road for {b}. Didn't mind the dust." } },
            { "passby|did:done|fresh", new[] { "{who} walked right past me. Looked, and walked on.", "Lying there in the dirt, and {who} stepped around me.", "Lay there in the dirt and {who} just looked. Just looked.", "Boots went past my head. {who}'s boots. Never slowed." } },
            { "passby|did:done|chewing", new[] { "{who}. Wouldn't stop for a fallen neighbour.", "Every time I see {who} I'm down in that dirt again.", "{who} walked right past me. I'll remember the boots.", "{who} and I pass most days. Neither of us mentions the dirt." } },
            { "passby|did:done|letting", new[] { "{who} walked past me once. Old news. Mostly.", "{who} left me lying in the street, once. A body doesn't forget that.", "{who} stepped past me in the dirt, that time. Not forgot.", "I got up on my own, that day. {who} saw to that." } },
            { "passby|did:doer|fresh", new[] { "{who} took a tumble. Not my business.", "Should I have stopped for {who}? Well. Didn't.", "Not my business, {who} falling. Kept walking.", "Saw {who} go down and my feet kept on. They know best, maybe." } },
            { "passby|did:doer|chewing", new[] { "{who}'s fine. People fall. People get up.", "{who} giving me looks since. Over a fall. Folk are tender.", "{who} will have been fine. Was {he}? Didn't look back.", "People say I walked past {who}. I did. There it is." } },
            { "passby|saw|fresh", new[] { "{b} fell and {a} walked right on past. Cold.", "Saw {a} step round {b} like a puddle.", "{b} down in the dirt and {a} stepped round like it was a puddle.", "Saw {a} walk right over {b}, near enough. Not a glance." } },
            // standing up to a bully: defend (the one who stepped in, the one picked on), faced (the one who stepped in, the bully)
            { "defend|did:doer|fresh", new[] { "Stood between {who} and trouble. Knees still going.", "Couldn't watch it done to {who}. Wouldn't.", "Said my piece to the bully for {who}. Voice held, mostly.", "Stepped in for {who}. Hands shook after, not during." } },
            { "defend|did:doer|chewing", new[] { "Would I do it again, for {who}? I would.", "Thought of what might've happened to {who}. Glad I spoke.", "The bully's been glaring at me since. Let him glare. {who}'s worth it.", "Folk look at me a shade longer since I stood up for {who}. It'll serve." } },
            { "defend|did:done|fresh", new[] { "{who} stepped in for me. Didn't have to.", "Thought I was done for. Then {who} spoke up.", "{who} stepped between us. I could have wept.", "{who} said leave it, and the bully left it. Just like that." } },
            { "defend|did:done|chewing", new[] { "Owe {who} for that. I know it.", "Keep thinking how {who} just stood there and said no.", "Can't stop seeing {who} standing there, chin up.", "Can't pay {who} back for that. Can try." } },
            { "defend|did:done|letting", new[] { "{who} stood up for me, once. That's a friend.", "When it came to it, {who} stood by me. That's the whole of it.", "{who} spoke up for me, back then. It stuck.", "When it mattered, {who} said no for me. Don't forget it." } },
            { "defend|saw|fresh", new[] { "{a} stood up for {b}. Took some nerve.", "Saw {a} step in for {b}. Wouldn't have had the stomach myself.", "{a} told the bully off for {b}. Whole street went quiet.", "{a} got between {b} and the bully. Didn't flinch." } },
            { "faced|did:doer|fresh", new[] { "Looked {who} in the eye and told it plain.", "{who}'s the kind that needs telling. So I told.", "Told {who} plain to quit it. {who} didn't care to hear it.", "Said quit it to {who}'s face. {he} didn't quit it. But {he} heard." } },
            { "faced|did:done|fresh", new[] { "{who}, sticking a nose in where it's not wanted.", "Who asked {who}? Nobody asked.", "Who's {who} to tell me my business? Nobody, that's who.", "{who} spoke to me like I was a boy. In the street. In front of everybody." } },
            { "faced|did:done|chewing", new[] { "{who} made a fool of me in the street. That's owed.", "Every time I see {who} I hear it again.", "{who} shamed me in front of the street. I won't let that lie.", "{who} will get it back. Not today. Owed, though." } },
            // a round bought: the one buying (doer), the one stood a drink (done), and those who saw it
            { "round|did:doer|fresh", new[] { "Bought the house a round. Purse lighter. Heart too.", "{who} drank my health. Felt good to be thanked.", "Whiskey all round, and every face turned my way. Felt tall.", "Barkeep winked at me. First time ever." } },
            { "round|did:doer|chewing", new[] { "Spent too free last night. Don't regret it. Much.", "Coins I'll miss come Friday. Worth it, mostly.", "The thanks have worn off. The purse hasn't filled back up.", "Friends for a night, every one of them. Cheap at the price. Nearly." } },
            { "round|did:done|fresh", new[] { "{who} stood us all a drink. Good sort.", "Whiskey on {who}. Still warm in the chest.", "Didn't pay for a drop last night. {who} saw to that.", "{who} raised a glass to the whole room. Even me." } },
            { "round|did:done|chewing", new[] { "Owe {who} a drink now. Fair is fair.", "Ought to stand {who} one back. Next time I'm flush.", "{who} stood me a drink. Haven't the coin to stand one back. Yet.", "Think of {who} kindly. Whiskey does that. Kindness does, too." } },
            { "round|saw|fresh", new[] { "{a} bought a round. Bet {a} regrets it come morning.", "Saw {a} stand the house a drink. Must be flush.", "Whole saloon cheering {a}. Easy to be loved with money.", "{a} slapped coins on the bar. {b} grinning ear to ear." } },
            // a debt paid in the street: the one who paid (doer), the one paid (done), and those who saw it counted out
            { "settled|did:doer|fresh", new[] { "Square with {who}. Said out loud, in the street. Good.", "Eleven dollars gone. Felt like a hundred lifted off.", "Counted it into {who}'s hand coin by coin. Every eye on us.", "Light in the pocket. Lighter in the chest." } },
            { "settled|did:doer|chewing", new[] { "No more crossing the street when {who} comes. That's worth eleven dollars.", "Folk saw me pay {who}. Good. Let them see the honest ones too.", "Lighter purse, straighter back. Squared with {who}.", "Still owe the store. But {who}'s paid, and {who} talks." } },
            { "settled|did:done|fresh", new[] { "{who} paid. Every coin. Counted them twice.", "Had {who} down as a deadbeat. Wrong, for once.", "{who} paid up in the open. Never thought I'd see it.", "{who} put the money in my hand in front of everybody. Didn't expect that." } },
            { "settled|did:done|chewing", new[] { "{who}'s good for it, it turns out. I'll remember that.", "{who} paid. Takes a bigger man than I took {him} for.", "Had the money a week now. Still half expect {who} to ask for it back.", "{who} counted it out in the road. Everybody saw {he} was good for it." } },
            { "settled|saw|chewing", new[] { "{a} and {b}, square now. Town will want something else to talk about.", "{a} paying {b} in the street. Still think well of {a} for it.", "That money {a} handed {b}. Half the town counted along.", "{a} and {b}, square. Somebody will owe somebody again by Saturday." } },
            { "settled|saw|letting", new[] { "{a} paid {b} back, that time. Comes to mind when I see the two of them.", "{a} paid {b} in the open, once. Don't see that often enough.", "{a} and {b} and the coins in the road. Remember it well.", "Saw {a} square a debt with {b}, that time. Decent." } },
            { "settled|did:doer|letting", new[] { "Owed {who} once. Paid it. Sleep easier for it yet.", "Paid {who} off in the street, once. Did it loud on purpose.", "{who} and that debt. Long cleared. Still proud of the clearing.", "Squared with {who}, a while back. Haven't owed a man since." } },
            { "settled|did:done|letting", new[] { "{who} paid up, that time. Remember it when folks talk.", "{who} settled up, that time. I lend easier now. To {him}, anyhow.", "That debt {who} cleared. Nice to be wrong about a man.", "Got paid by {who}, once, when I'd given it up. Good feeling. Rare." } },
            // comfort (a friend's sympathy, a hurt seen to, a kind answer): both of them, and those who saw it
            { "comfort|did|fresh", new[] { "Quiet words with {who} today. Sorrow's lighter shared.", "{who} and I talked soft. Some things need saying soft.", "Hand on my shoulder, from {who}. Didn't know I needed it.", "{who} and I. Not many words. Enough." } },
            { "comfort|did|chewing", new[] { "Keep coming back to what {who} and I said. Hard days.", "Glad of {who}, this week. Glad of anybody.", "Thinking of what {who} said. Soft words. They stuck.", "Hard days. {who} makes them a shade lighter." } },
            { "comfort|did|letting", new[] { "{who}, that day. Kindness in a hard week.", "{who} sat with me when it was bad. That's what friends are.", "A hard week, once, and {who} in it with me. Keep that.", "{who}'s soft words, back then. They've lasted." } },
            { "comfort|saw|fresh", new[] { "{a} and {b} talking low. Somebody's had bad news.", "Saw {b} take {a}'s hand a moment. Sorrow, by the look of it.", "{b} leaning close to {a}, voice low. Bad news, likely.", "Saw {a}'s face fall. {b} stood by. Good of {b}." } },
            { "comfort|saw|chewing", new[] { "Whatever it was between {a} and {b}, it looked heavy.", "{a} and {b}, the other day. Bad news is easier shared, I suppose.", "Still think of {a}'s face, and {b} close by. Somebody's gone, likely.", "Whatever {b} said to {a}, it steadied {a}." } },
            { "comfort|saw|letting", new[] { "{a} and {b}, heads together, that sad day.", "{a} and {b}, that sad week. Good to see folk stand by each other.", "That hard time of {a}'s. {b} was there. I remember who was there.", "{a}'s bad news, back then. {b} shared the weight of it." } },
            { "cheer|did|fresh", new[] { "Good news today, and {who} glad of it with me.", "{who} and I, grinning like fools. Good day.", "{who} and I laughed till the dog barked. Good day.", "Good news, and {who} the first to shake my hand." } },
            { "cheer|saw|fresh", new[] { "{a} and {b}, laughing in the street. Somebody's had good news.", "{a} slapped {b} on the back so hard {b} near fell. Good news, then.", "{a} and {b}, grinning like fools on the corner. Nice to see.", "Somebody's had luck. {a} and {b} were laughing fit to burst." } },
            { "apology|did|fresh", new[] { "{who} said sorry. Didn't expect it. Don't know what to do with it.", "Got a sorry out of {who}. Well.", "{who} said sorry, plain as that. Wasn't ready for it.", "A sorry from {who}. Don't know whether to shake {his} hand or check my pockets." } },
            { "apology|saw|fresh", new[] { "{a} owned up to {b} in the street. Takes some doing.", "{a} said sorry to {b} right there in the road. Didn't look easy.", "Saw {a} own it to {b}. Hat in hand, near enough.", "{a} and {b}, and {a} saying sorry first. Didn't expect that." } },
            { "round|saw|chewing", new[] { "{a}'s round, still talked of. Cheap way to buy friends. Works, though.", "{a}'s round. Folk still say {his} name warmer for it.", "{a} bought the house a drink. Wonder what {he} wanted.", "Still hearing about {a}'s round. Cheap, for what it bought." } },
            { "round|did:doer|letting", new[] { "Stood the house a round, once. Folk still nod to me for it.", "Bought the house a round once. Best money I ever threw away.", "That round. Men still say my name kindly for it.", "Stood a round, a while back. Purse forgot it long before I did." } },
            { "round|did:done|letting", new[] { "{who} bought for the room, that night. Good night, that.", "{who} bought for the house, that time. Still drink to {him} now and then.", "A free drink from {who}, once. Remember it when I'm dry.", "{who}'s round. Good night. Few enough of those." } },
            { "cheer|did|chewing", new[] { "Still smiling at what {who} and I laughed about.", "{who}'s laugh. Keep hearing it. Keeps me going.", "Good day, that, with {who}. Still warm from it.", "Told {who} the news and {he} whooped. Whooped. In the street." } },
            { "cheer|did|letting", new[] { "{who}, laughing in the street with me. A good day, that was.", "A good day with {who}, a while back. Keep those by.", "{who} and I, glad together once. Rare enough.", "That good news. {who} was the one I told. That's the whole of it." } },
            { "cheer|saw|chewing", new[] { "{a} and {b} were glad of something yesterday. Wish I knew what.", "{a} and {b}, so pleased the other day. Hope it holds.", "Whatever {a} and {b} were laughing at, I could've used some.", "Good news for {a}, by the look. {b} glad of it. Nice." } },
            { "apology|did|chewing", new[] { "{who}'s sorry keeps turning over in my head. Meant it, I think.", "Can't stay sore at {who} after that. Trying, a little.", "{who} meant it, I think. Sorry's hard to say and {he} said it.", "Keep wondering what it cost {who} to say sorry. Something." } },
            { "apology|did|letting", new[] { "{who} said sorry, once. I've let it go. Mostly.", "{who} owned up, once. Made it easier to be civil ever since.", "That sorry from {who}. Didn't fix all of it. Fixed enough.", "{who} apologised, a while back. Rare thing, in {town}." } },
            { "apology|saw|chewing", new[] { "{a} owned it to {b}'s face. Takes more backbone than most have.", "{a} saying sorry to {b}. Still think better of {a} for it.", "{a} owned up in the street. Takes something. More than I've got, some days.", "{a} apologised to {b}, that day. Town's a shade kinder for it." } },
            { "help|saw|chewing", new[] { "{a} helping {b} up. Decent of {a}. Not everyone would.", "Keep thinking of {a} kneeling down for {b}. I'd have walked by. Hope not.", "{a} helped {b} up. Town's a little better for it.", "{a} stopped for {b}. Still turning that over." } },
            { "passby|did:doer|letting", new[] { "{who} took a spill, that time. I had places to be.", "Walked past {who} on the ground once. Wasn't my best day.", "{who} fell, I walked on. That's how it was.", "Didn't stop for {who}. Long ago. Still a little sorry." } },
            { "passby|saw|chewing", new[] { "{a} walked past {b} lying there. Cold, that.", "{a} stepping round {b} like that. I've not looked at {a} the same since.", "Still see {b} on the ground and {a}'s back going away.", "{a} left {b} lying there. Town noticed. Town notices that." } },
            { "defend|did:doer|letting", new[] { "Stood by {who} when it counted. I'd do it again.", "Stood up for {who}, once. Didn't come to blows. Still counts.", "{who} and the bully, that time. Said my piece. Glad of it yet.", "Spoke up for {who} when nobody else would. Keep that one." } },
            { "defend|saw|chewing", new[] { "{a} sticking up for {b} like that. Takes backbone.", "{a} standing up for {b}. More nerve than I've got.", "Still think of {a} saying no for {b}. Plain no.", "{a} and {b}, and the bully. {a} came out of it taller." } },
            { "faced|did:doer|chewing", new[] { "{who} glares at me now. Fine. Somebody had to say it.", "{who}'s nursing it. Let {him}. I'd say it again.", "Crossed {who} in the street, and {he} won't let it be. Fine.", "Hear {who}'s been telling folk I meddled. Call it that." } },
            { "faced|did:done|letting", new[] { "{who} crossed me, once, in the street. I remember.", "{who} stuck {his} nose in once. I've a long memory for noses.", "{who}, and that day in the street. Not settled. Just quiet.", "Somebody shamed me in the road once. {who}. I keep it." } },
            { "settled|saw|fresh", new[] { "{a} paid {b} back right there in the street. Counted out loud.", "Saw money change hands. {a} and {b}, square at last.", "{b} counting coins aloud in the street. {a} standing there, red to the ears.", "{a} paid {b} on the corner. Every coin out loud. Took nerve." } },
            { "helpup|did|fresh", new[] { "{you} gave me a hand up when nobody else would.", "Knee aches. But {you} stopped. I'll remember it.", "Sat in the dirt like a fool, and {you} gave me a hand. Kind.", "Down in the road and {you} came straight over. Didn't have to." } },
            { "helpup|did|chewing", new[] { "Owe {you} for that. Somehow.", "Told everybody how {you} helped me up. Half didn't believe it.", "{you}. Pulled me up like I weighed nothing.", "Keep thinking of {you}'s hand coming down. Didn't think, just reached." } },
            { "helpup|did|letting", new[] { "{you}. A kind hand, once. I keep it.", "Fell in the street, once. {you} stopped. Most don't.", "{you} picked me up, that day. Say it to anyone who speaks ill of him.", "Fell once, got a hand from {you}. The town's wrong about him, maybe." } },
            { "helpup|did|near", new[] { "There's {you}. The one who helped me up.", "{you}'s here. Ought to say thank you again.", "{you}, close by. Nod to him. He stopped for me.", "There's {you}. Knee still remembers the fall. I remember the hand." } },
            // whiskey for the house, on him (Core/Fondness.cs; SIXDAY item 1): a round he bought them
            { "house|did|fresh", new[] { "{you} stood the whole house a drink. Mine too.", "Whiskey on {you}. Whole room grinning like fools.", "{you} bought the house a round. Didn't have to. Did.", "Drank {you}'s whiskey tonight. Didn't pay for a drop." } },
            { "house|did|chewing", new[] { "Owe {you} a drink. Fair's fair.", "Still think of {you}'s round. Cheap way to buy a room. Bought me, anyway.", "{you} bought the house a drink. Wonder what he wanted. Maybe nothing.", "Told them at home a stranger bought the house a round. {you}. They didn't believe it." } },
            { "house|did|letting", new[] { "{you} stood the house a round, once. Good night, that.", "A free drink from {you}, that night. Remember it when I'm dry.", "{you}'s round. Few enough of those in {town}.", "That night {you} bought for the house. Still drink to him now and then." } },
            { "house|did|near", new[] { "There's {you}. Bought the house a round. Nod to him.", "{you}'s here. Ought to stand him one back. Haven't the coin.", "There's the man who bought the house a drink. {you}. Decent.", "{you}, close by. Whiskey's still warm in the memory." } },
            // the debt he covered while the creditor stood over them in the street (Core/Fondness.cs; SIXDAY item 1)
            { "debtpaid|did|fresh", new[] { "{you} paid what I owed. In the street, with the whole town looking on. Just paid it.", "Square. {you} made me square. I can breathe.", "Thought I'd lose the mule. Then {you} put the money in his hand.", "{you} counted it out and the man walked off. Like it was nothing." } },
            { "debtpaid|did|chewing", new[] { "Owe {you} now, not him. A better man to owe.", "Keep seeing {you} count out the dollars. Didn't even ask my name.", "Can't think why {you} did it. Won't ask, either.", "Told them at home. {you}, a stranger, paid it. They didn't believe me." } },
            { "debtpaid|did|letting", new[] { "{you} paid my debt, once. I'll not forget it if I live to ninety.", "Square with the world since the day {you} paid for me.", "{you}. The one who paid what I owed. Say it to anyone who speaks ill of him.", "There was a debt, once. {you} ended it. That's the whole story." } },
            { "debtpaid|did|near", new[] { "There's {you}. The man who paid my debt. Hat off to him.", "{you}'s here. Ought to pay him back. Will, some day.", "There's {you}. I was a ruined man till he came by.", "{you}, close by. Still owe him. Always will, in a way." } },
            // walked home through the dark by the stranger (WestworldScript.Escort.cs)
            // ten dollars lent by the player, and an introduction made by him (Core/Verbs.cs; SIXDAY item 6): {who} the one introduced to
            { "loan|did|fresh", new[] { "{you} lent me ten dollars. Three days, I said. Three days.", "Ten dollars from {you}, on my word alone. Don't let him down.", "A loan from a near stranger. {you}. The world's not all bad.", "His money in my pocket. Feels heavier than ten dollars should." } },
            { "loan|did|chewing", new[] { "{you}'s ten dollars. Counting the days.", "Owe {you}. Owe is a word that sits on the chest.", "Pay {you} first. Before the store, before the saloon.", "Three days. Where's ten dollars to come from in three days?" } },
            { "loan|did|letting", new[] { "{you} lent me money once, when it counted.", "Borrowed from {you}. Paid or not, I remember the lending.", "There was a time {you} trusted me with ten dollars. Not many have.", "A loan from {you}, a while back. I think of it when I'm short." } },
            { "loan|did|near", new[] { "There's {you}. His ten dollars. Smile, and don't run.", "{you}'s here. Have I got his money? Not all of it.", "The man who lent me the ten. Straighten up.", "{you}. Pay him, or steer wide. Pay him." } },
            { "introduced|did|fresh", new[] { "{you} made me known to {who} today. A face I'd seen about. A name now.", "Introduced to {who} by {you}, like gentlefolk. I'll remember it.", "{who}. Met proper, through {you}. We'll nod now.", "{you} put {who}'s hand in mine. Odd thing for a stranger to do. Kind, though." } },
            { "introduced|did|chewing", new[] { "{who} nodded to me in the street. {you}'s doing, that.", "Knew {who} to see. Know {who} to speak to now, thanks to {you}.", "{you} went to the trouble of making me known to {who}. Few would.", "Saw {who} today. We spoke. {you} started that." } },
            { "introduced|did|letting", new[] { "{you} introduced me to {who}, once. Friends since, near enough.", "Met {who} through {you}. The town's smaller for it, in the good way.", "{who} and I go back to the day {you} put us together.", "A stranger made me known to {who}. {you}. I think of it when we pass." } },
            { "introduced|did|near", new[] { "There's {you}. The one who made me known to {who}. A nod's owed.", "{you}'s about. Ought to tell him {who} and I get on.", "{you}. Introduced me to {who}. Decent of him.", "The man who put me and {who} together. Tip the hat." } },
            // the circuit judge and gallows day (Core/Trials.cs): the player's word in court, a hanging seen or heard of, a verdict the town split on, a prisoner got away
            { "perjury|did|fresh", new[] { "{you} stood up in that court and swore to a thing I watched not happen.", "I saw it with my own eyes. {you} told the judge otherwise, cool as milk.", "A lie under oath. {you}'s. I was ten feet from what happened." } },
            { "perjury|did|chewing", new[] { "Still turning it over. {you} swore false and the judge wrote it down.", "What else has {you} lied about, if he'll lie to a judge?", "{you} lied for that man in court. I'll not say it in the street. I'll not forget it either." } },
            { "perjury|did|letting", new[] { "{you} once swore black was white in a courtroom. I was there.", "There was a trial. {you} lied at it. That's all I know of his word.", "I keep my distance from {you}. A man who'll lie under oath will lie anywhere." } },
            { "spokefor|did|fresh", new[] { "{you} stood up for the dead man today when nobody else would.", "Said it plain to the judge, {you} did. Somebody had to.", "{you} spoke the truth in that court. The dead can't thank him. I can." } },
            { "spokefor|did|chewing", new[] { "{you} gave his word for the dead man. The town took note.", "If it weren't for {you} speaking up, that killing would have gone for nothing.", "{you}, at the trial. A stranger with more spine than the half of us." } },
            { "spokefor|did|letting", new[] { "{you} spoke for the dead once, in court. I've liked him since.", "There was a trial here. {you} told the truth at it. Not everyone did.", "A man who'll stand up in a courtroom for somebody in the ground: that's {you}." } },
            { "spokeagainst|did|fresh", new[] { "{you} put the rope round a friend of mine's neck with ten words.", "Spoke against him, {you} did. In front of the whole town.", "{you} had no call to speak in that court. He did anyway." } },
            { "spokeagainst|did|chewing", new[] { "{you}'s word did it. A stranger's word, against one of ours.", "I'd not have thought {you} would testify. Shows what I know.", "Can't look at {you} the same. Not after the trial." } },
            { "spokeagainst|did|letting", new[] { "{you} testified against a man of this town, once. Some of us remember.", "There's a trial between me and {you}. Always will be.", "{you}. The stranger who spoke in court. Enough said." } },
            { "acquittal|heard|fresh", new[] { "{who} walked out of that court free, and a man in the ground. That's the law.", "Not guilty. {who}. Say it to the widow.", "{who} walks the street tonight. The dead man doesn't." } },
            { "acquittal|heard|chewing", new[] { "I'll not drink where {who} drinks. Not now.", "Half the town's shaking {who}'s hand. The other half's crossing the street.", "The judge let {who} go. The town hasn't." } },
            { "acquittal|heard|letting", new[] { "There was a trial. {who} walked. I've not spoken to him since.", "{who}'s free man these weeks. Free of the law. Not of me.", "Some things a town doesn't forgive. {who} walking out of that court is one." } },
            { "walkedfree|heard|fresh", new[] { "{who}'s free. It was a fight, that's all it ever was.", "The judge saw it right. {who} could have been any of us.", "They've let {who} go. I could weep." } },
            { "walkedfree|heard|chewing", new[] { "Half the town's not speaking to the other half. Over {who}.", "{who} walked free and I'll stand by him. Let them stare.", "Bought {who} a drink. Somebody had to, the way the room looked at him." } },
            { "walkedfree|heard|letting", new[] { "{who} stood trial once and walked. The town's never been the same since.", "There was a trial. {who} was cleared. Some still hold it against him.", "{who}, a free man. I was glad then. I'm glad now." } },
            { "hanging|saw|fresh", new[] { "Watched them hang {who} this morning. Didn't see the drop. Heard it.", "{who}. On the wagons we stood, and the sound of it. The sound.", "They hanged {who}. I knew him to nod to. I nodded this morning, God help me." } },
            { "hanging|saw|chewing", new[] { "Keep hearing the trap. Keep hearing it.", "{who} walked up to it himself. I couldn't have.", "Haven't eaten right since the hanging. {who}'s face at the end." } },
            { "hanging|saw|letting", new[] { "I stood outside when they hanged {who}. Never again.", "There's a hanging in me now that wasn't there before. {who}'s.", "{who}. The stockade. The quiet after. I don't talk about it." } },
            { "hanging|heard|fresh", new[] { "They hanged {who} this morning. I stayed home.", "{who}'s dead by the rope. The whole town's quiet.", "Heard the crowd go silent from my window. That was {who}." } },
            { "hanging|heard|chewing", new[] { "{who}. Hanged. In this town.", "The paper has the hanging. I'll not read it.", "Glad I didn't go and see {who} hang. Sorry too." } },
            { "hanging|heard|letting", new[] { "They hanged {who} here once. The town doesn't say his name.", "There was a hanging. {who}. Before your time, maybe.", "{who} hanged at the jail. I kept away. I still keep away from the jail." } },
            { "jailbreak|heard|fresh", new[] { "{you} got him out of the jail. Out. With a man dead and unanswered for.", "The sheriff's asking who. I know who. {you}.", "{you} took the law's man out of the law's hands last night. God's own nerve." } },
            { "jailbreak|heard|chewing", new[] { "A dead man's friends don't forget who opened the cell. {you}.", "{you} did the breaking out. The whole town knows it and says nothing.", "The judge came for nothing, thanks to {you}." } },
            { "jailbreak|heard|letting", new[] { "{you} once emptied the jail here. Ask anybody.", "There was a man held for a killing. {you} let him out. That's {you}.", "The law never got its man. {you} saw to that." } },
            { "friendfreed|heard|fresh", new[] { "{you} got my friend out of that cell. I don't ask how.", "He'd have hanged. {you} saw he didn't.", "{you}. Whatever else he is, he opened that door." } },
            { "friendfreed|heard|chewing", new[] { "Owe {you} a friend's life. Don't know how to pay that.", "{you} did what the rest of us only talked about.", "If {you} ever needs a door opened in this town, mine's open." } },
            { "friendfreed|heard|letting", new[] { "{you} broke a friend of mine out of the jail, once. I'd do a lot for {you}.", "There's a man alive somewhere because of {you}. I know which man.", "{you}. The jail. I remember." } },
            { "gallowsbroken|heard|fresh", new[] { "{you} fired on the hanging and the killer ran. Ran! With the rope on the beam.", "A town does the law's work and {you} undoes it with a gun.", "{you}'s shots. The crowd on the ground and the condemned man gone." } },
            { "gallowsbroken|heard|chewing", new[] { "{you} let a killer go at the gallows. The dead man's people know it.", "There'll be no justice here now. {you} saw to that.", "Shots at a hanging. {you}. The sheriff has his name and so do I." } },
            { "gallowsbroken|heard|letting", new[] { "{you} once broke up a hanging here. Ask the dead man's family what they think of him.", "There was a hanging that never happened. {you}'s doing.", "{you} fired at the gallows. A town remembers that longer than the hanging." } },
            { "friendsaved|heard|fresh", new[] { "{you} fired and the stockade broke and my friend ran. I'll never forget it.", "He was at the rope's end. {you} got him off it.", "{you}. The shots. My friend alive. That's all I know and all I need." } },
            { "friendsaved|heard|chewing", new[] { "{you} saved a man from the rope. Half the town hates him for it. Not me.", "They'd have hanged him. {you} wouldn't let it be.", "Drank to {you} last night. Quietly. The dead man's people were in the room." } },
            { "friendsaved|heard|letting", new[] { "{you} stopped a hanging in this town. I was for it. I still am.", "A friend of mine lives because {you} fired when nobody else would.", "{you}. The gallows. I'd stand with him anywhere after that." } },
            // the Wild West show (Core/Shows.cs): the act seen or heard of, and the real one standing up in the crowd
            { "wildwest|saw|fresh", new[] { "Saw the show on the ground outside town. The man in the gray hat shot six. Blanks, but I jumped.", "A Wild West show, here. The riders were good. The act was better. They say the real one's in the territory.", "Fifty cents for the show. Worth a dollar. The boys will be playing it in the street for a month." } },
            { "wildwest|saw|chewing", new[] { "Keep thinking about the show. The real one, they said. Out there somewhere.", "The riders in the ring were playing a man who's alive and about. That's a strange thing to pay to see.", "Everyone at the bar's an expert on the act now. Half of them weren't there." } },
            { "wildwest|saw|letting", new[] { "There was a Wild West show here once. They acted out a thing that happened not far off.", "I saw them play the man in the gray hat in a ring. I've wondered since if I ever passed the real one.", "The show came through. The riders, the blanks, the bill. The town talked of nothing else for a week." } },
            { "wildwest|heard|fresh", new[] { "Missed the show. They say the act was the man from the news, done with blanks and horses.", "The whole town went to the show but me. I heard it from the street, near enough.", "A show on the ground outside town. Didn't go. Heard the shooting from here and knew it for blanks." } },
            { "wildwest|heard|chewing", new[] { "Everybody's talking about the show. The real one, they keep saying.", "Should have gone to the show. The way they tell it, it was something.", "The paper has the show in it. Fifty cents I saved and a week of hearing about it." } },
            { "wildwest|heard|letting", new[] { "A Wild West show came through once. I didn't go. Everyone who did still talks of it.", "They acted out a killing from the news in a ring outside town. I stayed home. Sounded foolish. Still does.", "There was a show. The real one was in the territory then, they said. Maybe he still is." } },
            { "revealed|saw|fresh", new[] { "{you} stood up at the show and said it was him. The real one. I was six feet off.", "The man in the ring was playing {you}. Then {you} stood up. The ring looked small after that.", "{you}. At the show. 'That's me,' he said, or as good as. Nobody breathed." } },
            { "revealed|saw|chewing", new[] { "Can't stop telling it. {you}, standing up in the crowd. Some left. I stayed.", "{you} let the whole town know what he is. That's either the bravest thing or the vainest.", "Think about {you} standing up at the show. Would I have? No." } },
            { "revealed|saw|letting", new[] { "{you} once stood up at a Wild West show and said he was the man in the act. I was there.", "The show came through and {you} stood up as the real one. The town's told it a hundred ways since.", "{you}. The crowd. The barker lost for words. I don't forget it." } },
            // the reset (Core/LoopVoice.cs): a friend come back to the start of their loop, and the ones tied to them noticing
            { "reset|heard|fresh", new[] { "{who}'s {who} again. Too much so. Whistling.", "{who} came in whistling. {who} hasn't whistled in a month.", "Something's gone out of {who}. Or come back. Can't tell which." } },
            { "reset|heard|chewing", new[] { "Asked {who} about the thing that was eating {who}. Looked at me blank. Blank as a plate.", "{who} is cheerful. It's the wrong size of cheerful.", "Whatever {who} saw, {who} doesn't see it now. I almost envy it." } },
            { "reset|heard|letting", new[] { "{who} went strange for a while, then went ordinary again. The ordinary was the stranger thing.", "I remember {who} standing in the street at three in the morning with a broom. {who} doesn't.", "{who}'s fine now. Everybody says so. Everybody says it a little too quick." } },
            // the reload noticed (Core/Ghosts.cs): a kiss or a quarrel the world took back, kept by both sides
            { "ghostkiss|heard|fresh", new[] { "Kissed {who}. Or dreamed it. {who} looks at me like I dreamed it.", "There was a moment with {who} yesterday. {who} says there wasn't. One of us is lying and it isn't my mouth.", "{who}, close enough to... no. That didn't happen. Then why do I know the smell of {who}'s coat?" } },
            { "ghostkiss|heard|chewing", new[] { "Keep reaching for a day with {who} in it that the calendar hasn't got.", "{who} and I had something, for an afternoon that never came. I'd like it back.", "Asked {who} about it sideways. {who} looked at me sideways back." } },
            { "ghostkiss|heard|letting", new[] { "There's a kiss between me and {who} that neither of us had. Funny what you keep.", "{who}. The afternoon that wasn't. I don't bring it up.", "Whatever didn't happen with {who}, it stays with me more than most things that did." } },
            { "ghostquarrel|heard|fresh", new[] { "I had words with {who} yesterday. {who} says we didn't. One of us is wrong and it isn't the bruise.", "{who} and I fell out. Then we hadn't. Then {who} nodded good morning like a fool.", "Shouted at {who}. I remember the spit. {who} remembers nothing." } },
            { "ghostquarrel|heard|chewing", new[] { "Can't look at {who} without hearing the quarrel we didn't have.", "{who} owes me an apology for a thing that never happened. I'll not get it.", "Woke angry at {who}. For nothing. For a nothing I can taste." } },
            { "ghostquarrel|heard|letting", new[] { "{who} and I have a quarrel somewhere that the world mislaid. I keep my side of it.", "There's a day missing between me and {who}. A bad one. Good riddance, maybe.", "Civil with {who}, these days. Civil like two people who nearly weren't." } },
            { "broughtin|did|fresh", new[] { "{you} trussed me and carried me to the sheriff like a hog to market. Ten dollars, it cost me.", "Thirty days or ten dollars, on {you}'s say-so. I paid. I'll remember.", "{you} brought me in. Me. In front of the whole town." } },
            { "broughtin|did|chewing", new[] { "Ten dollars lighter, thanks to {you}. He'll be ten dollars sorrier one day.", "The deputy laughed when {you} carried me in. I heard him.", "{you} and his rope. I'll not forget the feel of it." } },
            { "broughtin|did|letting", new[] { "{you} once hogtied me and sold me to the law. We're not friends.", "There's a fine I paid because of {you}. I keep the receipt.", "{you}. The man who brought me in. Some things don't fade." } },
            { "escort|did|fresh", new[] { "{you} walked me home. Kept pace, kept his distance. Kind.", "Saw me to my door last night. {you}. Asked nothing for it.", "{you} saw me home. The street was black and I was afraid, and then I wasn't.", "Home safe, and {you} to thank for it. Didn't think I'd sleep. Slept." } },
            { "escort|did|chewing", new[] { "Owe {you} for that walk. Don't know how to pay it.", "Keep thinking of {you} walking beside me in the dark. Said nothing. Didn't need to.", "{you} saw me home. Told the neighbours. They didn't know what to make of it.", "That walk with {you}. Felt like somebody cared whether I got there." } },
            { "escort|did|letting", new[] { "{you} saw me home, one night. I remember it when the street's dark.", "A walk home, once, with {you}. Small thing. Kept it.", "{you}. Walked me to my door the night I was afraid. That's the whole of what I know of him.", "That night {you} saw me home. Long ago now. Still think well of him." } },
            { "escort|did|near", new[] { "There's {you}. Saw me home, once. Nod to him.", "{you}'s here. The one who walked me home. Ought to say so.", "There's {you}. I was afraid of the dark that night. He wasn't.", "{you}, close by. Safe home, thanks to him. Remember it." } },
            // a word carried between two who'd quarrelled (WestworldScript.Errand.cs): the sender, and the one it was for
            { "errand|did|fresh", new[] { "{you} carried my word to {who}. Mended, and I never had to say it to {who}'s face.", "Gave {you} my sorry to carry. {who} took it. I can breathe.", "{you} went between {who} and me. A stranger. Did what I couldn't.", "Square with {who} again, and {you} the one who carried it." } },
            { "errand|did|chewing", new[] { "Owe {you} for going between. {who} and I nod again.", "Keep thinking how {you} carried that word. Didn't ask why.", "Told {who} I was sorry, by {you}. Cheaper than saying it. Worked, though.", "{you} mended what I broke with {who}. Decent." } },
            { "errand|did|letting", new[] { "{you} carried a word for me, once. To {who}. Mended it.", "There was a quarrel with {who}, once. {you} went between. That's how it ended.", "{you}. Went between {who} and me. I'd not have thought to ask anyone else.", "A word carried, once, by {you}. {who} and I are friends yet." } },
            { "errand|did|near", new[] { "There's {you}. Went between {who} and me. Nod to him.", "{you}'s here. The one who carried my word. Ought to thank him again.", "There's {you}. Carried my sorry to {who}. Decent man.", "{you}, close by. I think of {who} and the word he carried." } },
            { "errandback|did|fresh", new[] { "{you} carried my word to {who}. {who} sent it back. Still. {you} tried.", "Sent my sorry by {you}. {who} wouldn't have it. Not {you}'s fault.", "{you} went between. {who}'s stubborn. Decent of {you}, all the same." } },
            { "errandback|did|chewing", new[] { "{you} carried it and {who} sent it back. I'll go myself, one day.", "Keep thinking of {you} going to {who} for me. Kind. Wasted, but kind." } },
            { "errandback|did|letting", new[] { "{you} carried a word to {who}, once. Came to nothing. Kind of {you}, though.", "A word by {you}, once. {who} never took it. Not {you}'s doing." } },
            { "errandto|did|fresh", new[] { "{you} brought me {who}'s word. Sorry, by a stranger. Took it anyway.", "{you} went between {who} and me. Odd. Kind.", "{who} sent {you} with a word. Mended more than I'd say.", "A stranger with {who}'s sorry. {you}. Decent of him to carry it." } },
            { "errandto|did|chewing", new[] { "Keep thinking of {you} standing there with {who}'s word. Took some gall.", "{you} carried {who}'s sorry. Who does that for a stranger?", "Square with {who}, and {you} the cause. Owe him a drink." } },
            { "errandto|did|letting", new[] { "{you} brought me a word from {who}, once. Mended it.", "There was a quarrel with {who}. {you} carried the sorry. That ended it.", "{you}. The go-between. Think of him when I see {who}." } },
            { "errandto|did|near", new[] { "There's {you}. Carried {who}'s word to me. Nod to him.", "{you}'s here. Went between {who} and me. Decent man.", "There's the go-between. {you}. Nod to him." } },
            // a coin for the music (WestworldScript.Menu.cs: the Talk list on a performer)
            { "tip|did|fresh", new[] { "{you} dropped a coin in the hat. Most walk by.", "A coin from {you}. Played the next one for him.", "{you} paid for the music. Remember the face." } },
            { "tip|did|chewing", new[] { "{you} tipped. Most don't. Keep that face.", "Played better after {you}'s coin. Funny, that." } },
            { "tip|did|letting", new[] { "{you} dropped a coin once. For the music. Still remember it.", "A man who paid for the music, once. {you}." } },
            { "tip|did|near", new[] { "There's {you}. Dropped a coin for the music. Play one for him.", "{you}'s in. He pays. Play the good one." } },
            // an ally who fell standing with the player (Core/Engine.Allies.cs): those who knew them hear of it
            { "ally|heard|fresh", new[] { "{who} died standing with {you}. {you}'s quarrel, {who}'s blood.", "{who}'s dead. Went in for {you}, they say, and never came out.", "They buried {who} today. {you} walked away from it. {who} didn't.", "{who} took a bullet meant for {you}. Say that slowly. Then say who's to blame." } },
            { "ally|heard|chewing", new[] { "Keep seeing {who} going in after {you}. Didn't have to.", "{who} would be alive if {you} had never come to {town}.", "Folks nod to {you} still. I can't. {who}'s not here to.", "{who} died for {you}. {you} owes this town a life, by my count." } },
            { "ally|heard|letting", new[] { "{who} died standing with {you}, back then. I've not forgotten who walked away.", "It was {you}'s fight that took {who}. I think of it when {you} rides in.", "{who}. Dead for {you}. Time's dulled it. Not much.", "They say {who} chose it. Maybe. {you}'s still the one it was for." } },
            { "ally|heard|near", new[] { "There's {you}. {who} died for him. I'll not nod.", "{you}'s in town. {who} isn't. That's the whole of what I feel.", "There's {you}, alive. {who} stood by him and isn't.", "{you}, close by. The man {who} died for. Walk on." } },
            // a campfire shared after dark (WestworldScript.Campfire.cs): the stranger who sat with them
            { "campfire|did|fresh", new[] { "{you} sat at our fire last night. Drank our coffee. Listened.", "Stranger came in off the road and sat a spell. {you}. Good company.", "Told {you} the tale by the fire. Laughed in the right places.", "{you}. Shared our fire. Rode on at dawn like a decent man." } },
            { "campfire|did|chewing", new[] { "That fellow at the fire. {you}. Wonder where he rode to.", "Keep thinking of {you} by the fire, hat down, saying little.", "{you} sat with us. Didn't rob us, didn't preach. Rare, that.", "Good night, that one. {you}, the coffee, the dark all round." } },
            { "campfire|did|letting", new[] { "Shared a fire with {you}, once. Out past the road somewhere.", "{you}. Sat at our fire one night. Think of him when I smell woodsmoke.", "A stranger at the fire, once. {you}. Decent company.", "{you} and the fire and the cold. Long ago now. Still warm." } },
            { "campfire|did|near", new[] { "There's {you}. The one from the fire. Nod to him.", "{you}'s here. In town, of all places. Sat at our fire once.", "There's {you}. Shared our coffee. Ought to say hello.", "{you}, close by. Last saw him by firelight." } },
            { "deed:kindness|saw|fresh", new[] { "{you} stepped in. Didn't have to. Did.", "Saw {you} do a decent thing. Didn't think he had it in him.", "Didn't think {you} the kind. Saw it with my own eyes, so.", "Saw {you} do right by a stranger. Not what they say of him." } },
            { "deed:kindness|saw|chewing", new[] { "Can't make {you} out. The things they say, and what I saw.", "Told it at supper, what {you} did. Nobody believed me.", "Keep weighing what I saw {you} do against what I've heard. The seeing wins, so far.", "A good turn from {you}. Keep turning it over." } },
            { "deed:kindness|saw|letting", new[] { "{you}. Decent, once, where I could see it. I remember that.", "A kindness from {you}. Still turns over in my head.", "{you} did a kind thing once where I could see. Hold onto that.", "That kindness of {you}'s. Didn't expect it then. Half expect it now." } },
            { "deed:kindness|saw|near", new[] { "There's {you}. Nod to him. He earned a nod.", "{you}'s near. Strange, to feel safer for it.", "{you}'s near. The one who did right. Doesn't look it. Didn't then.", "There's {you}. A kind man, or near enough. Let him pass easy." } },
            { "mercy|saw|fresh", new[] { "{you} had him at gunpoint and let him go. I'd not have.", "Gun up, then down. {you} let the man live.", "{you} could have killed him. Didn't. Not many wouldn't.", "Saw {you} lower the gun. The man ran. {you} let him." } },
            { "peace|saw|fresh", new[] { "{you} broke it up before it got ugly. Somebody had to.", "Saw {you} step between them. Sense, at last, in this town.", "{you} got between them and nobody got hurt. Rare in {town}.", "Two men fit to kill each other, and {you} talked them down. Talked." } },
            // ---- the player's flirting, by the answer it got ({you}: him as they know him) -------------------------
            { "flirt:yes|did|fresh", new[] { "{you} looked at me like I was the only one in the room. Foolish. Lovely.", "Said yes to {you} with my eyes before my mouth caught up.", "{you} said something sweet and I forgot every word but the way he said it.", "Heart going like a bird. {you}. Of all the men." } },
            { "flirt:yes|did|chewing", new[] { "Keep catching myself smiling. {you}, of all men.", "Wonder if {you} meant it. Men say things.", "Said yes too fast. Would say it faster.", "{you}'s not been by. Sweep the step anyhow." } },
            { "flirt:yes|did|letting", new[] { "{you}. A sweet thing to remember, whatever comes of it.", "Haven't seen {you} in days. Not that I'm counting.", "{you}, and that day. Whatever came of it, it was mine.", "Think of {you} less. Not never." } },
            { "flirt:yes|did|near", new[] { "There's {you}. Don't fuss with your hair. Don't.", "{you}'s close. My face is hot. Stupid face.", "{you}. Smooth the apron. Don't smooth the apron.", "There's {you}. Chin up, eyes down, and don't grin." } },
            { "flirt:maybe|did|fresh", new[] { "{you} tried his luck. Didn't say no. Didn't say yes.", "Can't make up my mind about {you}. That's something, at least.", "{you} said his piece. I said nothing. Nothing's not no.", "Didn't send {you} off. Didn't ask him to stay. Don't know." } },
            { "flirt:maybe|did|chewing", new[] { "Turning {you} over in my head like a coin.", "Would it be so terrible? {you}. Maybe.", "Keep weighing {you}. He's heavier each time.", "Ask Mother what she'd say of {you}. Know already. Ask anyhow." } },
            { "flirt:maybe|did|near", new[] { "{you} again. Let him work for it.", "There's {you}. Keep your face straight.", "{you}, across the way. Don't look. Looked.", "There's {you}. Make him wonder. Wondering myself." } },
            { "flirt:no|did|fresh", new[] { "{you} tried his luck. Not with me, mister.", "The nerve of {you}. Walked up like he owned the street.", "{you} and that honeyed tongue. Keep it for the women upstairs.", "Sent {you} on his way. Didn't raise my voice. Didn't need to." } },
            { "flirt:no|did|chewing", new[] { "Still sore {you} thought I'd be so easy.", "Told {you} no. Felt good, saying it.", "Still cross about {you}. Crosser I let him get a word in.", "A man like {you}, thinking a smile buys something. Not here." } },
            { "flirt:no|did|letting", new[] { "{you} hasn't tried again. Good.", "Funny. I half expected {you} to try again.", "{you} keeps his distance now. Suits me.", "Said no to {you} once. It's kept." } },
            { "flirt:no|did|near", new[] { "There's {you}. Look somewhere else.", "{you}. Don't let him catch your eye.", "{you}'s about. Keep busy. Keep moving.", "There's {you}. If he comes this way I've somewhere to be." } },
            { "flirt:afraid|did|fresh", new[] { "{you} came close and said sweet things. All I saw was the gun on his hip.", "Heart going like a drum. Not the way {you} hoped.", "Said something nice back to {you}. Didn't mean it. Wanted him gone.", "{you} smiled, and I counted the steps to the door." } },
            { "flirt:afraid|did|chewing", new[] { "Can't forget how close {you} stood.", "Smiled at {you} so he'd go. He went. My hands shook after.", "Don't go to the store alone now. Since {you}.", "{you} meant it kindly, maybe. Didn't feel kind. Felt like being cornered." } },
            { "flirt:afraid|did|near", new[] { "{you}. Don't look at him. Don't give him a reason.", "There's {you}. Stay where people can see me.", "{you}'s close. Keep near the counter. Keep near somebody.", "There's {you}. Smile small. Say little. Let him go by." } },
            { "flirted|did|fresh", new[] { "{you} and his sweet talk. What a thing.", "Never had a stranger talk to me that way. Not lately.", "{you} tipped his hat and said a soft word. Still turning it over.", "A stranger with a sweet tongue. {you}. Hm." } },
            { "flirted|did|chewing", new[] { "Still thinking about {you} and what he said.", "{you}. Can't decide what I make of him.", "{you} and that pretty speech. Half a mind to believe it.", "Haven't told a soul what {you} said. Keep it for myself." } },
            { "flirted|did|letting", new[] { "{you} and his sweet talk. Seems a while ago now.", "A man said a pretty thing to me once. {you}. Days back.", "{you}, a while back, with the sweet words. A nice thing to have had said.", "Forgot most of what {you} said. Remember how it felt." } },

            // ---- deaths: heard of (a friend, a foe, someone known) and seen ------------------------------------
            { "friend|heard|fresh", new[] { "{who}'s dead. Said it out loud and it still isn't so.", "Last thing I said to {who} was about the weather. The weather.", "{who}. Gone. The word doesn't fit in my mouth.", "Sat down when they told me about {who}. Had to. Legs went." } },
            { "friend|heard|chewing", new[] { "Walked past {who}'s door and slowed. Habit.", "Folks keep saying {who} is in a better place. Folks didn't know {who}.", "Set two cups out this morning. Habit. {who}'s cup.", "Can't go in the saloon. {who}'s stool is there and nobody's on it." } },
            { "friend|heard|letting", new[] { "Days since {who}. The quiet where {he} used to be is getting familiar.", "Laughed at something today. Then remembered {who}. Felt like stealing.", "Said {who}'s name today without my voice going. First time.", "{who} would've laughed at that. I laughed for the both of us." } },
            { "foe|heard|fresh", new[] { "{who}'s dead. I ought to feel something. I'm waiting.", "So {who} is gone. Nobody left to be sore at.", "{who}'s dead. We never settled it. Now we never will.", "Heard about {who} and felt nothing. Then felt something. Odd." } },
            { "foe|heard|chewing", new[] { "Said hard things of {who}. Can't take them back now. Wouldn't, maybe.", "Folks look at me since {who} died. As if I wished it. Did I?", "Catch myself readying a sharp word for {who}. Nobody to say it to.", "{who} in the ground. Told myself I'd dance. Didn't." } },
            { "foe|heard|letting", new[] { "{who}. The old quarrel went in the ground too.", "Funny thing, missing a quarrel.", "{who}. We'd have made it up, given years. Didn't get the years.", "Miss having {who} to be sore at. Strange thing to miss." } },
            { "known|heard|fresh", new[] { "{who}'s dead, they say. Saw {him} only last week.", "{who}. Didn't know {him} well. Knew {him} enough.", "{who}'s gone. Nodded to {him} a hundred times. Never once stopped.", "Word of {who}'s death came with the bread. Odd, how news comes." } },
            { "known|heard|chewing", new[] { "{who} was here, and now isn't. That's all a life is, some days.", "Keep thinking of the last time I passed {who}. Didn't even nod.", "Keep expecting {who} at the usual corner. Corner's empty.", "Didn't know {who} well. Still, the street's a face short." } },
            { "known|heard|letting", new[] { "Town's already filling the space {who} left.", "Hard to call up {who}'s face already. That's the worst of it.", "{who}. Gone a while now. Somebody else has the corner.", "Think of {who} when I pass that house. Less each time." } },
            { "death|saw|fresh|bold", new[] { "Saw {who} die. Quick. There are worse ways.", "{who} dropped and stayed dropped. Seen it before. Never gets easier.", "{who} went down and I didn't look away. Somebody ought to see a man die.", "Seen {who} die. Said a word over {him}. Nobody else would." } },
            { "death|saw|fresh|fearful", new[] { "{who} died right there. Right there, in front of me.", "Watched the life go out of {who}. Can't feel my hands.", "{who} fell and I couldn't move. Still can't, some part of me.", "The sound {who} made. I'll hear it tonight. I know I will." } },
            { "death|saw|fresh|cold", new[] { "{who} is dead. Somebody will want the coat.", "Saw {who} go. Didn't owe {him} anything. Still.", "{who}'s dead. One more debt nobody collects.", "Saw {who} go down. Finished my drink. What else is there to do." } },
            { "death|saw|fresh|plain", new[] { "{who}, dead in the dirt. A minute ago, alive.", "Saw {who} die. Took my hat off. Didn't know what else to do.", "{who} died in the road and the dogs barked and that was all.", "Closed {who}'s eyes. Hands shook doing it." } },
            { "death|saw|chewing|bold", new[] { "Keep seeing {who} fall. Didn't flinch then. Flinching now.", "Death's quick out here. {who} found that out.", "{who} died badly. I'll die better. I've decided it.", "Still see {who} fall when I shut my eyes. Don't shut them much." } },
            { "death|saw|chewing|fearful", new[] { "Every shot I hear now, I think of {who}.", "Keep my eyes on the ground where {who} fell. Can't help it.", "Won't walk that street. Not since {who}.", "Sleep with the lamp lit. {who}'s face in the dark otherwise." } },
            { "death|saw|chewing|cold", new[] { "{who}'s things will go cheap. Somebody ought to see to it.", "Dead is dead. {who} won't mind what I think.", "{who}'s room will be let by Sunday. Town doesn't wait.", "People ask how {who} died. I say quickly. It's what they want." } },
            { "death|saw|chewing|plain", new[] { "Wonder if {who} had people. Somebody ought to write.", "Keep going back to the spot where {who} fell.", "Said a prayer for {who}. Don't know if it took. Said it anyhow.", "Keep thinking {who} had a mother once. Everybody does." } },
            { "death|saw|letting", new[] { "Days since {who} died in front of me. Still see it some nights.", "{who}. A name now, and a patch of ground I walk around.", "{who}'s death. Comes back on grey days. Fewer grey days now.", "Saw {who} die, that time. Talk of it less. Think of it about the same." } },

            { "thiefcaught|saw|fresh", new[] { "{you} caught the thief. Collared him like a stray dog.", "Saw {you} grab that pickpocket. About time somebody did.", "{you} had the thief by the collar before the shout was done. Quick.", "Watched {you} catch that pickpocket. Town owes him a drink for it." } },
        };

        /// Every memory line, for the tests and the overlap checks.
        public static IEnumerable<string> AllLines()
        {
            return Pools.Values.SelectMany(x => x);
        }
    }
}
